<script setup lang="ts">
import type { MonthFee } from '~/types/models'
const {t}=useLanguage(),db=useSupabase(),key=useRequestKey(),financialError=useFinancialError()
const emit=defineEmits<{saved:[]}>()
const month=ref(nowMonth()),query=ref(''),accounts=ref<MonthFee[]>([]),selected=ref<MonthFee|null>(null),history=ref<any[]>([]),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),periodOpen=ref(false)
const form=reactive({amount:null as number|null,date:'',method:'',reference:'',notes:''})
const matches=computed(()=>accounts.value.filter(r=>`${r.student_name} ${r.student_code} ${r.class_name}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())).slice(0,30))
let version=0,selectionVersion=0
async function load(){const own=++version;selectionVersion++;selected.value=null;history.value=[];accounts.value=[];periodOpen.value=false;if(!db)return;loading.value=true;error.value='';try{if(!isValidMonth(month.value))throw Error(t('financialUi.finance.monthInvalid'));const p=await db.from('billing_periods').select('id,status').eq('year_month',monthStart(month.value)).maybeSingle();if(p.error)throw p.error;if(own!==version)return;periodOpen.value=p.data?.status==='open';if(p.data){const periodId=p.data.id;const data=await allRows(()=>db.from('month_fee_overview').select('*').eq('period_id',periodId).order('id'));if(own===version)accounts.value=data as MonthFee[]}}catch(e){if(own===version)error.value=financialError(e)}finally{if(own===version)loading.value=false}}
async function choose(row:MonthFee){if(!db)return;const own=++selectionVersion;selected.value=row;history.value=[];key.reset();Object.assign(form,{amount:null,date:'',method:'',reference:'',notes:''});const receipts=await allRows(()=>db.from('payments').select('*').eq('monthly_membership_id',row.id).order('created_at',{ascending:false}).order('id')).catch(e=>{error.value=financialError(e);return []});if(own===selectionVersion)history.value=receipts}
async function save(){if(!db||!selected.value||saving.value)return;error.value='';success.value='';if(!form.amount||form.amount<0||form.amount>Number(selected.value.balance_due)||!form.date||!form.method){error.value=t('agreements.invalid');return}saving.value=true;try{const membership=selected.value.id;const payload={p_membership:membership,p_amount:form.amount,p_date:form.date,p_method:form.method,p_note:[form.reference,form.notes].filter(Boolean).join(' | ')||null};const r=await db.rpc('record_tuition_payment',{...payload,p_request:key.forPayload(payload)});if(r.error)throw r.error;success.value=t('financialUi.finance.paymentSaved');key.reset();await load();const account=accounts.value.find(r=>r.id===membership);if(account)await choose(account);emit('saved')}catch(e){error.value=financialError(e)}finally{saving.value=false}}
watch(month,load);onMounted(load)
</script>
<template><section id="record-payment" class="card payment-recorder"><h2>{{t('agreements.recordPayment')}}</h2><Notice :message="error" kind="error"/><Notice :message="success" kind="success"/><fieldset :disabled="saving" class="payment-fields"><div class="form-grid"><label>{{t('registration.month')}}<input v-model="month" type="month" required/></label><label>{{t('registration.search')}}<input v-model="query" :placeholder="t('registration.placeholder')"/></label></div><p v-if="loading">{{t('common.loading')}}</p><p v-else-if="!accounts.length&&!error">{{t('agreements.empty')}}</p><div class="payment-matches"><button v-for="row in matches" :key="row.id" type="button" class="btn" :aria-pressed="selected?.id===row.id" @click="choose(row)">{{row.student_name}} · {{row.student_code}} · {{row.class_name}} · {{t('agreements.'+row.confirmation_status)}} · {{money(row.balance_due)}}</button></div><form v-if="selected" @submit.prevent="save"><h3>{{selected.student_name}} · {{selected.class_name}}</h3><dl class="summary-box"><div v-for="field in (['agreed_fee','discount','amount_due','paid_total','balance_due'] as const)" :key="field" class="summary-row"><dt>{{t('registration.'+field)}}</dt><dd>{{money(selected[field])}}</dd></div></dl><div class="form-grid"><label>{{t('financialUi.finance.receivedAmount')}}<input v-model.number="form.amount" type="number" min="0.01" :max="selected.balance_due" step="0.01" required/></label><label>{{t('registration.paymentDate')}}<input v-model="form.date" type="date" required/></label><label>{{t('registration.paymentMethod')}}<select v-model="form.method" :aria-label="t('registration.paymentMethod')" required><option value="">{{t('registration.choosePaymentMethod')}}</option><option value="cash">{{t('financialUi.finance.cash')}}</option><option value="bank">{{t('financialUi.finance.bank')}}</option><option value="other">{{t('financialUi.expenses.other')}}</option></select></label><label>{{t('registration.paymentReference')}}<input v-model="form.reference"/></label><label class="wide">{{t('registration.paymentNote')}}<textarea v-model="form.notes"/></label></div><Notice v-if="!periodOpen" :message="t('registration.closed')" kind="error"/><div class="form-footer"><button class="btn primary" :disabled="saving||!periodOpen||Number(selected.balance_due)<=0">{{t('financialUi.finance.saveReceipt')}}</button></div><h3>{{t('financialUi.finance.paymentHistory')}}</h3><p v-if="!history.length">{{t('financialUi.materials.noPayments')}}</p><div v-for="receipt in history" :key="receipt.id" class="summary-row"><span>{{receipt.paid_on}} · {{t('financialUi.finance.'+receipt.method)}} · {{receipt.reference_note}} · {{receipt.voided_at?t('financialUi.voided'):t('financialUi.valid')}}</span><strong>{{money(receipt.amount)}}</strong></div></form></fieldset></section></template>
<style scoped>.payment-recorder{margin:20px 0;border-top:4px solid #6366f1}.payment-fields{border:0;padding:0;min-width:0}.payment-matches{display:flex;flex-wrap:wrap;gap:8px;max-height:220px;overflow:auto;margin:16px 0}dd{margin:0}h3{margin:20px 0}</style>
